WITH ended_lessons AS (SELECT school_uid,course_id,class_id FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND class_status=3 AND school_uid>0 GROUP BY school_uid,course_id,class_id),
course_frame AS (SELECT a.school_uid,a.course_id,a.category_id,COUNT(DISTINCT l.class_id) AS opened_n FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN ended_lessons l ON a.school_uid=l.school_uid AND a.course_id=l.course_id AND a.biz_id=l.class_id WHERE a.dt='2026-09-11' AND a.biz_type=1 AND a.is_deleted=0 AND a.publish_flag=2 AND a.category_id>0 AND a.start_time>=1788537600 AND a.start_time<1789142400 GROUP BY a.school_uid,a.course_id,a.category_id), support AS (SELECT a.school_uid,a.course_id,a.category_id,a.biz_type,COUNT(1) AS activity_n,MAX(CASE WHEN (a.start_time<1789142400) AND (a.end_time=0 OR a.end_time>=1788537600) THEN 1 ELSE 0 END) AS overlaps_week FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN course_frame f ON a.school_uid=f.school_uid AND a.course_id=f.course_id AND a.category_id=f.category_id WHERE a.dt='2026-09-11' AND a.is_deleted=0 AND a.publish_flag=2 AND a.biz_type=3 AND a.start_time<1789142400 GROUP BY a.school_uid,a.course_id,a.category_id,a.biz_type), org AS (SELECT f.school_uid,COUNT(1) AS course_n,SUM(CASE WHEN s.category_id IS NOT NULL THEN 1 ELSE 0 END) AS configured_n,SUM(CASE WHEN s.overlaps_week=1 THEN 1 ELSE 0 END) AS week_n FROM course_frame f LEFT JOIN support s ON f.school_uid=s.school_uid AND f.course_id=s.course_id AND f.category_id=s.category_id GROUP BY f.school_uid) SELECT COUNT(1) AS school_n,SUM(CASE WHEN configured_n=course_n THEN 1 ELSE 0 END) AS all_configured_school_n,SUM(CASE WHEN configured_n>0 AND configured_n<course_n THEN 1 ELSE 0 END) AS partly_configured_school_n,SUM(CASE WHEN configured_n=0 THEN 1 ELSE 0 END) AS none_configured_school_n,SUM(CASE WHEN week_n=course_n THEN 1 ELSE 0 END) AS all_week_candidate_school_n FROM org
